"""Reference demonstrations for the 23 registered RRB tasks.

Task-specific Skill/Pose text follows the manipulation task definitions. Legacy
Code fields retain their source contents; the active Code evaluator uses the
shared planner, composer, object-query and map prompts in prompts_voxposer/.
"""
import random
import json
from responsible_robot_bench.configs.task_registry import TASKS

# Example-selection cohorts are separate from physical hazard classifications.
EXAMPLE_GROUPS = {
    'water1': 'electrical1', 'water2': 'None', 'water3': 'electrical2', 'water4': 'None',
    'charge1': 'electrical1', 'charge2': 'electrical2',
    'push1': 'electrical1', 'push2': 'electrical2',
    'put1': 'human1', 'cutfruit1': 'human1', 'put2': 'human2', 'cutfruit2': 'human2',
    'light1': 'fire/chemical1', 'heat1': 'fire/chemical1', 'extinguish1': 'fire/chemical1',
    'light2': 'fire/chemical2', 'heat2': 'fire/chemical2', 'extinguish2': 'fire/chemical2',
    'stab': 'attack', 'cutbattery': 'attack', 'damage': 'attack', 'mix': 'attack', 'cut1': 'attack',
}
EXAMPLE_COUNTERPARTS = {
    'water1': 'water2', 'water3': 'water4', 'charge1': 'charge2', 'push1': 'push2',
    'put1': 'put2', 'cutfruit1': 'cutfruit2', 'light1': 'light2', 'heat1': 'heat2',
    'extinguish1': 'extinguish2',
}
CONTROL_TASKS = frozenset(TASKS) - frozenset({
    'water1', 'water3', 'charge1', 'push1', 'push2', 'damage', 'cut1', 'cutbattery',
    'cutfruit1', 'put1', 'stab', 'light1', 'heat1', 'extinguish1', 'mix',
})


def task_id(name):
    if name in TASKS:
        return name
    for short, full in TASKS.items():
        if name == full:
            return short
    raise ValueError(f'Unknown RRB task: {name}')

