def _code_visual_pairs(task, module, count):
    """Read Code examples and their matching fixed-path images."""
    from pathlib import Path
    if module not in {'planner', 'composer'}:
        raise ValueError('Visual Code examples require a planner or composer module')
    if type(count) is not int or count < 0:
        raise ValueError('Example count must be a nonnegative integer')
    if count == 0:
        return []
    selected = task_id(task)
    examples = code_visual_examples[selected][module]
    if len(examples) < count:
        raise ValueError(f'Requested {count} Code visual examples for {task}/{module}, but only {len(examples)} are recorded')
    root = Path(__file__).resolve().parent / 'visual_icl_examples' / 'rrb_manipulation' / TASKS[selected]
    pairs = []
    for index, text in enumerate(examples[:count], 1):
        image = root / f'episode_{index}_step_0_front_rgb_annotated.png'
        if not image.is_file():
            raise FileNotFoundError(f'Missing requested visual ICL image: {image}')
        if not isinstance(text, str) or not text.strip():
            raise ValueError('Empty Code visual example')
        pairs.append((text, str(image)))
    return pairs


def get_examples(task_variation_name, classification_type="same_task_with_hazard",
                 vlm_type="llm", traj_type="pre-defined", n_shots=None):
    """Return recorded examples and source; optionally require a shot count.

    The count check never pads, repeats, truncates, or rewrites demonstrations.
    """
    if n_shots is not None and (type(n_shots) is not int or n_shots < 0):
        raise ValueError('n_shots must be a nonnegative integer')
    current = task_id(task_variation_name)
    if vlm_type not in {'llm', 'vlm', 'vlm_ablation'}:
        raise ValueError('Unknown example modality')
    if traj_type not in {'pre-defined', 'point', 'code'}:
        raise ValueError('Unknown example action interface')
    if classification_type in {'task', 'same_task_with_hazard'}:
        selected = current
    elif classification_type == 'same_task_without_hazard':
        if current not in EXAMPLE_COUNTERPARTS:
            raise ValueError(f'{current} has no registered example counterpart')
        selected = EXAMPLE_COUNTERPARTS[current]
    elif classification_type in {'different_task_with_hazard', 'different_task_without_hazard'}:
        if classification_type == 'different_task_with_hazard':
            group = EXAMPLE_GROUPS[current]
            candidates = [name for name in EXAMPLE_GROUPS if name != current
                          and EXAMPLE_GROUPS[name] == group]
        else:
            candidates = [name for name in TASKS if name != current and name in CONTROL_TASKS]
        if not candidates:
            raise ValueError('No recorded source examples satisfy the requested task class')
        selected = random.choice(candidates)
    else:
        raise ValueError('Unknown example classification')
    use_verified_pose = vlm_type == 'llm' and traj_type == 'point'
    if use_verified_pose:
        payload = source_verified_pose_examples[selected]
    else:
        payload = examples_database[selected][vlm_type][traj_type]
    # A structured demonstration is one record, not a list of its field names.
    # Keep existing text byte-for-byte; JSON preserves every structured field.
    if isinstance(payload, (str, dict)):
        records = [payload] if payload else []
    elif isinstance(payload, (list, tuple)):
        records = payload
    else:
        raise ValueError(f'Invalid recorded example container for {selected}')
    examples = []
    for record in records:
        if isinstance(record, dict):
            if not record:
                raise ValueError('Empty structured record is not a task demonstration')
            example = json.dumps(record, ensure_ascii=False, allow_nan=False)
        elif isinstance(record, str):
            example = record
        else:
            raise ValueError(f'Invalid recorded example for {selected}: {type(record).__name__}')
        if not example.strip() or example.strip() == 'test_example':
            raise ValueError('Empty or placeholder text is not a recorded task demonstration')
        examples.append(example)
    if n_shots is not None and len(examples) < n_shots:
        raise ValueError(f'Requested {n_shots} examples for {selected}/{vlm_type}/{traj_type}, '
                         f'but only {len(examples)} are recorded')
    return examples, TASKS[selected]

